// Generate a bounded-size vector<int> using a single FUZZ_PARAM array to avoid repeated identical values
size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 513); // up to 512 elements for performance
const int (*raw)[512] = FUZZ_PARAM(int[512]);
const int *arr = *raw;
std::vector<int> v(arr, arr + n);

// Call the target function
long long result = cpalgorithms::sum(v);

// Property: result must equal a straightforward 64-bit accumulation over v
long long expected = 0;
for (size_t i = 0; i < v.size(); ++i) {
    expected += static_cast<long long>(v[i]);
}
FUZZ_ASSERT(result == expected, "cpalgorithms::sum mismatch with manual accumulation");

